const r0=raw(0);const ss=(a,b,x)=>{x=Math.min(1,Math.max(0,(x-a)/(b-a)));return x*x*(3-2*x)};
const h=x=>{const t=Math.max(0,x-18);return (raw(x)-r0)*ss(0,70,t)};
