const fr=x=>x-Math.floor(x);const rnd=(i,s)=>fr(Math.sin(i*127.1+s*311.7)*43758.5453);
const lerp=(a,b,t)=>a+(b-a)*t;const ss=t=>t*t*(3-2*t);
function vn(x,p,s){const q=x/p,i=Math.floor(q),f=q-i;return lerp(rnd(i,s),rnd(i+1,s),ss(f));}
const raw=x=>(vn(x,38,1)-.5)*11+(vn(x,19,2)-.5)*5+(vn(x,8,3)-.5)*1.6+Math.sin(x*.009)*4;
const r0=raw(0);const ramp=x=>ss(Math.min(1,Math.max(0,(x-18)/60)));
const h=x=>(raw(x)-r0)*ramp(x);
