let mx=0,at=0;for(let x=0;x<3000;x+=.25){const s=(h(x+.25)-h(x-.25))/.5;if(Math.abs(s)>mx){mx=Math.abs(s);at=x}}console.log("max slope",mx.toFixed(2),"deg",(Math.atan(mx)*180/Math.PI).toFixed(0),"at",at);
let vals=[];for(let x=0;x<3000;x+=1)vals.push(h(x));console.log("min",Math.min(...vals).toFixed(1),"max",Math.max(...vals).toFixed(1));
