/* ------------------------------------------------------------------ */

function makeSoftTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.35, 'rgba(255,255,255,0.85)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const softTex = makeSoftTexture();

class ParticleField {
  constructor(capacity, { size = 0.4, additive = false, drag = 0.98, gravity = 3.2 } = {}) {
    this.capacity = capacity;
    this.gravity = gravity;
    this.drag = drag;
    this.cursor = 0;
    this.pos = new Float32Array(capacity * 3);
    this.vel = new Float32Array(capacity * 3);
    this.col = new Float32Array(capacity * 3);
    this.size = new Float32Array(capacity);
    this.alpha = new Float32Array(capacity);
    this.life = new Float32Array(capacity);
    this.max = new Float32Array(capacity);
    for (let i = 0; i < capacity; i += 1) {
      this.pos[i * 3 + 1] = -999;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    const mat = new THREE.ShaderMaterial({
      uniforms: {
        uTex: { value: softTex },
        uPixel: { value: Math.min(window.devicePixelRatio || 1, 2) }
      },
      vertexShader: `
        attribute float aSize;
        attribute float aAlpha;
        varying float vAlpha;
        varying vec3 vColor;
        uniform float uPixel;
        void main() {
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
          gl_PointSize = aSize * (280.0 / max(0.1, -mv.z)) * uPixel;
          vAlpha = aAlpha;
          vColor = color;
        }
      `,
      fragmentShader: `
        uniform sampler2D uTex;
        varying float vAlpha;
        varying vec3 vColor;
        void main() {
          vec4 tex = texture2D(uTex, gl_PointCoord);
          gl_FragColor = vec4(vColor, tex.a * vAlpha);
          if (gl_FragColor.a < 0.01) discard;
          #include <colorspace_fragment>
        }
      `,
      vertexColors: true,
      transparent: true,
      depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.geometry = geo;
    this.baseSize = size;
  }

  spawn(x, y, z, vx, vy, vz, life, color, size = 1) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % this.capacity;
    const p = i * 3;
    this.pos[p] = x;
    this.pos[p + 1] = y;
    this.pos[p + 2] = z;
    this.vel[p] = vx;
    this.vel[p + 1] = vy;
    this.vel[p + 2] = vz;
    const c = new THREE.Color(color);
    this.col[p] = c.r;
    this.col[p + 1] = c.g;
    this.col[p + 2] = c.b;
    this.size[i] = this.baseSize * size;
    this.life[i] = life;
    this.max[i] = life;
    this.alpha[i] = 0.9;
  }

  update(dt) {
    for (let i = 0; i < this.capacity; i += 1) {
      if (this.life[i] <= 0) {
        this.alpha[i] = 0;
        continue;
      }
      this.life[i] -= dt;
      const p = i * 3;
      this.vel[p] *= this.drag;
      this.vel[p + 1] -= this.gravity * dt;
      this.vel[p + 2] *= this.drag;
      this.pos[p] += this.vel[p] * dt;
      this.pos[p + 1] += this.vel[p + 1] * dt;
      this.pos[p + 2] += this.vel[p + 2] * dt;
      this.alpha[i] = Math.max(0, (this.life[i] / this.max[i]) * 0.8);
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.color.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
  }
}

const dust = new ParticleField(320, { size: 0.5, gravity: 2.4, drag: 0.975 });
const sparks = new ParticleField(180, { size: 0.2, gravity: 5.5, drag: 0.99, additive: true });
const smoke = new ParticleField(140, { size: 0.34, gravity: -0.15, drag: 0.985 });

function dustBurst(x, y, z, count, spread = 1, power = 1) {
  for (let i = 0; i < count; i += 1) {
    const a = Math.random() * Math.PI * 2;
    const r = Math.random() * spread;
    dust.spawn(
      x + Math.cos(a) * r,
      y + Math.random() * 0.35,
      z + Math.sin(a) * r * 0.7,
      (Math.random() - 0.5) * 3 * power,
      1.2 + Math.random() * 2.4 * power,
      (Math.random() - 0.5) * 2.5,
      0.55 + Math.random() * 0.7,
      [0xc79a68, 0xb98a5b, 0xd5b083][Math.floor(Math.random() * 3)],
      0.7 + Math.random() * 0.8
    );
  }
}

function sparkBurst(x, y, z, count, color = 0xffd45c) {
  for (let i = 0; i < count; i += 1) {
    const a = Math.random() * Math.PI * 2;
    const s = 1.5 + Math.random() * 3.5;
    sparks.spawn(
      x,
      y,
      z,
      Math.cos(a) * s,
      1.5 + Math.random() * 3,
      Math.sin(a) * s * 0.6,
      0.35 + Math.random() * 0.4,
      color,
      0.7 + Math.random() * 1.1
    );
  }
}

