const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const base = 'http://127.0.0.1:3002/';
(async () => {
  mkdirSync('screenshots', { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  for (const [name, viewport] of [['desktop', { width: 1440, height: 900 }], ['mobile', { width: 390, height: 844 }]]) {
    const page = await browser.newPage({ viewport, isMobile: name === 'mobile', hasTouch: name === 'mobile' });
    page.on('pageerror', e => console.log(name, 'PAGEERROR', e.message));
    page.on('console', m => { if (m.type() === 'error') console.log(name, 'CONSOLE', m.text()); });
    await page.goto(base, { waitUntil: 'load' });
    await page.waitForTimeout(1600);
    await page.screenshot({ path: `screenshots/menu-${name}.png` });
    console.log(name, 'menu cam', await page.evaluate(() => { const c = window.__ridgeRush.camera; return c.position.toArray().map(n => +n.toFixed(2)); }));
    await page.getByRole('button', { name: 'PLAY' }).click();
    await page.waitForTimeout(900);
    await page.screenshot({ path: `screenshots/play-${name}.png` });
    console.log(name, 'play cam', await page.evaluate(() => { const g = window.__ridgeRush; return { cam: g.camera.position.toArray().map(n => +n.toFixed(2)), car: [g.car.x, g.car.y, g.car.z], coins: g.world.activeCoins.length, coinPositions: g.world.activeCoins.slice(0, 8).map(c => [+c.position.x.toFixed(1), +c.position.y.toFixed(1)]) }; }));
    await page.keyboard.down('ArrowRight').catch(() => {});
    await page.waitForTimeout(2800);
    await page.keyboard.up('ArrowRight').catch(() => {});
    await page.waitForTimeout(200);
    await page.screenshot({ path: `screenshots/run-${name}.png` });
    console.log(name, 'run', await page.evaluate(() => { const g = window.__ridgeRush; return { state: g.state, x: +g.car.x.toFixed(1), y: +g.car.y.toFixed(2), speed: +g.car.speed.toFixed(1), angle: +g.car.angle.toFixed(2), coins: g.run?.coins, fuel: +g.run?.fuel.toFixed(1), contact: g.car.contactCount, crashed: g.car.crashed }; }));
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
