const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const base = 'http://127.0.0.1:3002/';

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  mkdirSync('screenshots', { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => { errors.push('PAGEERROR ' + e.message); console.log('PAGEERROR', e.message); });
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE ' + m.text()); console.log('CONSOLE', m.text()); } });

  await page.goto(base, { waitUntil: 'load' });
  await sleep(1400);

  // --- Touch pedal test via real CDP touch events ---
  const client = await context.newCDPSession(page);
  await page.getByRole('button', { name: 'PLAY' }).tap();
  await sleep(700);

  const gasBox = await page.locator('#gas-btn').boundingBox();
  const brakeBox = await page.locator('#brake-btn').boundingBox();
  const gasPt = { x: gasBox.x + gasBox.width / 2, y: gasBox.y + gasBox.height / 2, id: 1, radiusX: 8, radiusY: 8, force: 1 };
  const brakePt = { x: brakeBox.x + brakeBox.width / 2, y: brakeBox.y + brakeBox.height / 2, id: 2, radiusX: 8, radiusY: 8, force: 1 };

  await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [gasPt] });
  await sleep(2600);
  const gasState = await page.evaluate(() => ({
    gasClass: document.querySelector('#gas-btn').classList.contains('pressed'),
    state: window.__ridgeRush.state,
    x: +window.__ridgeRush.car.x.toFixed(2),
    speed: +window.__ridgeRush.car.speed.toFixed(2),
    fuel: +window.__ridgeRush.run.fuel.toFixed(1),
    coins: window.__ridgeRush.run.coins
  }));
  await page.screenshot({ path: 'screenshots/touch-gas-mobile.png' });
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await sleep(600);
  const released = await page.evaluate(() => ({
    gasClass: document.querySelector('#gas-btn').classList.contains('pressed'),
    speed: +window.__ridgeRush.car.speed.toFixed(2)
  }));

  // brake/reverse from stop
  await sleep(1200);
  const beforeBrake = await page.evaluate(() => window.__ridgeRush.car.x);
  await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [brakePt] });
  await sleep(1500);
  const brakeState = await page.evaluate(() => ({
    brakeClass: document.querySelector('#brake-btn').classList.contains('pressed'),
    x: +window.__ridgeRush.car.x.toFixed(2),
    speed: +window.__ridgeRush.car.speed.toFixed(2)
  }));
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await sleep(400);

  // --- Multi-touch binding via synthetic pointer events (both pedals, independent release) ---
  const multi = await page.evaluate(() => {
    const gas = document.querySelector('#gas-btn');
    const brake = document.querySelector('#brake-btn');
    const ev = (type, id) => new PointerEvent(type, { pointerId: id, pointerType: 'touch', bubbles: true, cancelable: true, isPrimary: id === 11 });
    gas.dispatchEvent(ev('pointerdown', 11));
    brake.dispatchEvent(ev('pointerdown', 12));
    const both = {
      gas: gas.classList.contains('pressed'),
      brake: brake.classList.contains('pressed')
    };
    gas.dispatchEvent(ev('pointerup', 11));
    const afterGasUp = {
      gas: gas.classList.contains('pressed'),
      brake: brake.classList.contains('pressed')
    };
    brake.dispatchEvent(ev('pointerup', 12));
    return { both, afterGasUp, afterAll: { gas: gas.classList.contains('pressed'), brake: brake.classList.contains('pressed') } };
  });

  // --- Long drive over hills: watch for crash/results ---
  await page.evaluate(() => window.__ridgeRush.startRun());
  await sleep(600);
  const gasBox2 = await page.locator('#gas-btn').boundingBox();
  const gasPt2 = { x: gasBox2.x + gasBox2.width / 2, y: gasBox2.y + gasBox2.height / 2, id: 3, radiusX: 8, radiusY: 8, force: 1 };
  await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [gasPt2] });

  const timeline = [];
  for (let i = 0; i < 16; i++) {
    await sleep(1000);
    const s = await page.evaluate(() => {
      const g = window.__ridgeRush;
      return {
        state: g.state,
        x: +g.car.x.toFixed(1),
        y: +g.car.y.toFixed(2),
        speed: +g.car.speed.toFixed(1),
        angle: +g.car.angle.toFixed(2),
        fuel: +(g.run?.fuel ?? -1).toFixed(1),
        coins: g.run?.coins ?? -1,
        crashed: g.car.crashed,
        resultsVisible: document.querySelector('#gameover').classList.contains('show')
      };
    });
    timeline.push(s);
    if (i === 6) await page.screenshot({ path: 'screenshots/touch-drive-1-mobile.png' });
    if (i === 13) await page.screenshot({ path: 'screenshots/touch-drive-2-mobile.png' });
    if (s.state === 'results') break;
  }
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] }).catch(() => {});
  await sleep(1200);
  await page.screenshot({ path: 'screenshots/touch-results-mobile.png' });

  const afterDrive = await page.evaluate(() => {
    const g = window.__ridgeRush;
    return {
      state: g.state,
      resultsVisible: document.querySelector('#gameover').classList.contains('show'),
      resultDistance: document.querySelector('#result-distance').textContent,
      resultCoins: document.querySelector('#result-coins').textContent,
      resultBest: document.querySelector('#result-best').textContent,
      savedCoins: g.save.coins,
      savedBest: g.save.best,
      saveRuns: g.save.runs,
      crashes: g.car.crashed
    };
  });

  // Retry from results via touch
  if (await page.locator('#retry-btn').isVisible()) {
    await page.locator('#retry-btn').tap();
    await sleep(900);
  } else {
    // ensure results for retry test
    await page.evaluate(() => { window.__ridgeRush.startRun(); });
    await sleep(300);
    await page.evaluate(() => { window.__ridgeRush.finishRun('crash'); });
    await sleep(700);
    await page.locator('#retry-btn').tap();
    await sleep(900);
  }
  const afterRetry = await page.evaluate(() => ({
    state: window.__ridgeRush.state,
    distance: document.querySelector('#distance').textContent,
    fuel: document.querySelector('#fuel-fill').style.width,
    overlay: document.querySelector('#gameover').classList.contains('show')
  }));

  // Results -> menu -> garage purchase flow
  await page.evaluate(() => { window.__ridgeRush.finishRun('crash'); });
  await sleep(900);
  await page.locator('#result-menu-btn').tap();
  await sleep(900);
  await page.evaluate(() => { window.__ridgeRush.save.coins = 600; });
  await page.locator('#garage-btn').tap();
  await sleep(900);
  await page.screenshot({ path: 'screenshots/garage-mobile.png' });
  const garage = await page.evaluate(() => ({
    state: window.__ridgeRush.state,
    open: document.querySelector('#garage').classList.contains('show'),
    cards: document.querySelectorAll('.vehicle-card').length,
    buttons: [...document.querySelectorAll('.vehicle-card button')].map(b => b.textContent.trim()),
    coins: window.__ridgeRush.save.coins
  }));
  // buy buggy (second card)
  const buyButtons = page.locator('.vehicle-card button');
  const buyCount = await buyButtons.count();
  let purchase = null;
  for (let i = 0; i < buyCount; i++) {
    const label = (await buyButtons.nth(i).textContent()).trim();
    if (/buy|unlock/i.test(label)) {
      await buyButtons.nth(i).tap();
      await sleep(700);
      purchase = { index: i, label };
      break;
    }
  }
  const afterBuy = await page.evaluate(() => ({
    coins: window.__ridgeRush.save.coins,
    selected: window.__ridgeRush.save.selected,
    owned: window.__ridgeRush.save.owned,
    buttons: [...document.querySelectorAll('.vehicle-card button')].map(b => b.textContent.trim())
  }));
  await page.screenshot({ path: 'screenshots/garage-bought-mobile.png' });
  await page.locator('#garage-close').tap();
  await sleep(700);
  const afterClose = await page.evaluate(() => ({
    state: window.__ridgeRush.state,
    garageOpen: document.querySelector('#garage').classList.contains('show'),
    menuOpen: document.querySelector('#menu').classList.contains('show')
  }));

  // Landscape sanity
  await page.setViewportSize({ width: 844, height: 390 });
  await sleep(900);
  await page.locator('#play-btn').tap();
  await sleep(900);
  await page.screenshot({ path: 'screenshots/play-landscape.png' });
  const landscape = await page.evaluate(() => ({
    state: window.__ridgeRush.state,
    carVisible: !!window.__ridgeRush.car,
    camera: window.__ridgeRush.camera.position.toArray().map(n => +n.toFixed(2)),
    pedals: [...document.querySelectorAll('.pedal')].map(p => { const r = p.getBoundingClientRect(); return { l: +r.left.toFixed(0), t: +r.top.toFixed(0), w: +r.width.toFixed(0), h: +r.height.toFixed(0) }; })
  }));

  console.log(JSON.stringify({
    gasState, released, beforeBrake: +beforeBrake.toFixed(2), brakeState, multi,
    timeline, afterDrive, afterRetry, garage, purchase, afterBuy, afterClose, landscape, errors
  }, null, 2));

  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

