const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const base = 'http://127.0.0.1:3002/';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  mkdirSync('screenshots', { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  for (const [name, viewport, mobile] of [['desktop', { width: 1440, height: 900 }, false], ['mobile', { width: 390, height: 844 }, true]]) {
    const context = await browser.newContext({ viewport, isMobile: mobile, hasTouch: mobile });
    const page = await context.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    await page.goto(base, { waitUntil: 'load' });
    await sleep(1300);
    if (mobile) await page.getByRole('button', { name: 'PLAY' }).tap();
    else await page.getByRole('button', { name: 'PLAY' }).click();
    await sleep(500);
    // Fake a meaningful run then crash into results.
    await page.evaluate(() => {
      const g = window.__ridgeRush;
      g.car.x = 486;
      g.run.maxX = 486;
      g.run.coins = 37;
      g.run.fuel = 41;
    });
    await sleep(300);
    await page.evaluate(() => window.__ridgeRush.finishRun('crash'));
    await sleep(1000);
    await page.screenshot({ path: `screenshots/results-${name}.png` });
    const results = await page.evaluate(() => ({
      state: window.__ridgeRush.state,
      show: document.querySelector('#gameover').classList.contains('show'),
      title: document.querySelector('#result-title').textContent,
      dist: document.querySelector('#result-distance').textContent,
      coins: document.querySelector('#result-coins').textContent,
      best: document.querySelector('#result-best').textContent,
      newBest: document.querySelector('#new-best').classList.contains('show'),
      retry: (() => { const r = document.querySelector('#retry-btn').getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; })()
    }));
    // Back to menu, garage, purchase toast on mobile
    await page.locator('#result-menu-btn').click();
    await sleep(800);
    await page.evaluate(() => { window.__ridgeRush.save.coins = 800; });
    await page.locator('#garage-btn').click();
    await sleep(800);
    const buttons = page.locator('.vehicle-card button');
    for (let i = 0; i < await buttons.count(); i++) {
      if (/unlock/i.test((await buttons.nth(i).textContent()).trim())) { await buttons.nth(i).click(); break; }
    }
    await sleep(500);
    await page.screenshot({ path: `screenshots/garage-toast-${name}.png` });
    console.log(name, JSON.stringify({ results, errors }));
    await context.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

