const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await sleep(1200);
  await page.getByRole('button', { name: 'PLAY' }).click();
  await sleep(500);

  // Move forward to load fuel chunk(s) and inspect pickups.
  const cans = await page.evaluate(async () => {
    const g = window.__ridgeRush;
    g.car.x = 240;
    await new Promise(r => setTimeout(r, 600));
    return g.world.activeFuel.map(c => ({ id: c.id, x: +c.x.toFixed(1), y: +c.y.toFixed(1), collected: c.collected }));
  });

  let pickup = null;
  if (cans.length) {
    pickup = await page.evaluate(async (can) => {
      const g = window.__ridgeRush;
      g.run.fuel = 50;
      g.car.x = can.x;
      g.car.y = can.y + 0.4;
      g.car.speed = 0;
      await new Promise(r => setTimeout(r, 300));
      return {
        fuel: +g.run.fuel.toFixed(1),
        collected: g.world.activeFuel.find(c => c.id === can.id)?.collected,
        state: g.state
      };
    }, cans[0]);
  }

  // Drive briefly with keyboard on desktop for input sanity.
  const x0 = await page.evaluate(() => window.__ridgeRush.car.x);
  await page.keyboard.down('ArrowRight');
  await sleep(1800);
  await page.keyboard.up('ArrowRight');
  await sleep(300);
  const keyboard = await page.evaluate(() => ({ x: +window.__ridgeRush.car.x.toFixed(1), speed: +window.__ridgeRush.car.speed.toFixed(1), state: window.__ridgeRush.state }));

  // Let the car run a while to exercise terrain/crash/landing code.
  await page.keyboard.down('ArrowRight');
  await sleep(12000);
  await page.keyboard.up('ArrowRight');
  await sleep(500);
  const longRun = await page.evaluate(() => {
    const g = window.__ridgeRush;
    return { state: g.state, x: +g.car.x.toFixed(1), fuel: +(g.run?.fuel ?? -1).toFixed(1), coins: g.run?.coins ?? -1, crashed: g.car.crashed, results: document.querySelector('#gameover').classList.contains('show') };
  });

  console.log(JSON.stringify({ cans, pickup, x0: +x0.toFixed(1), keyboard, longRun, errors }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

