const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  mkdirSync('screenshots', { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const cases = [
    ['small-phone', { width: 320, height: 568 }],
    ['iphone-se', { width: 375, height: 667 }],
    ['tablet', { width: 768, height: 1024 }],
    ['tablet-landscape', { width: 1024, height: 768 }]
  ];
  for (const [name, viewport] of cases) {
    const context = await browser.newContext({ viewport, isMobile: true, hasTouch: true });
    const page = await context.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
    await sleep(1200);
    const menuLayout = await page.evaluate(() => {
      const r = (sel) => { const e = document.querySelector(sel); if (!e) return null; const b = e.getBoundingClientRect(); return { l: +b.left.toFixed(0), t: +b.top.toFixed(0), r: +b.right.toFixed(0), b: +b.bottom.toFixed(0), w: +b.width.toFixed(0), h: +b.height.toFixed(0) }; };
      return { play: r('#play-btn'), garage: r('#garage-btn'), title: r('.title'), stats: r('.menu-stats'), content: r('.menu-content') };
    });
    await page.screenshot({ path: `screenshots/responsive-menu-${name}.png` });
    await page.getByRole('button', { name: 'PLAY' }).tap();
    await sleep(900);
    const playLayout = await page.evaluate(() => {
      const r = (sel) => { const e = document.querySelector(sel); if (!e) return null; const b = e.getBoundingClientRect(); return { l: +b.left.toFixed(0), t: +b.top.toFixed(0), r: +b.right.toFixed(0), b: +b.bottom.toFixed(0), w: +b.width.toFixed(0), h: +b.height.toFixed(0) }; };
      return {
        gas: r('#gas-btn'), brake: r('#brake-btn'), hint: r('#hint'),
        hud: r('.hud-top'), coin: r('.coin-pill'), fuel: r('.fuel-wrap'), mute: r('#mute-btn'),
        overflowX: document.documentElement.scrollWidth > innerWidth,
        overflowY: document.documentElement.scrollHeight > innerHeight
      };
    });
    await page.screenshot({ path: `screenshots/responsive-play-${name}.png` });
    console.log(name, JSON.stringify({ menuLayout, playLayout, errors }));
    await context.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

