function chooseVehicle(id) {
  const v = VEHICLES.find((item) => item.id === id);
  if (!v) return;
  if (!save.owned.includes(id)) {
    if (save.coins < v.price) {
      audio.denied();
      showToast('NOT ENOUGH COINS');
      return;
    }
    save.coins -= v.price;
    save.owned.push(id);
    audio.buy();
    showToast(`${v.name.toUpperCase()} UNLOCKED`);
  } else {
    audio.click();
  }
  save.vehicle = id;
  persist();
  createCar();
  car.reset(0);
  renderGarage();
  refreshMenuStats();
}

