    car.vy = 0;
    car.angVel = 0;
  });
  const timeline = [];
  for (let i = 0; i < 18; i++) {
    await sleep(300);
    timeline.push(await page.evaluate(() => {
      const g = window.__ridgeRush;
      return { t: +performance.now().toFixed(0), state: g.state, timer: +g.crashTimer.toFixed(2), y: +g.car.y.toFixed(2), crashed: g.car.crashed, results: document.querySelector('#gameover').classList.contains('show') };
