const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await sleep(1200);
  await page.getByRole('button', { name: 'PLAY' }).tap();
  await sleep(1500);
  const info = await page.evaluate(() => {
    const r = window.__ridgeRush.renderer;
    const gl = r.getContext();
    return {
      render: r.info.render,
      memory: r.info.memory,
      pixelRatio: r.getPixelRatio(),
      drawingBuffer: [gl.drawingBufferWidth, gl.drawingBufferHeight],
      renderer: gl.getParameter(gl.RENDERER),
      vendor: gl.getParameter(gl.VENDOR)
    };
  });
  // measure rAF fps over 3 seconds
  const fps = await page.evaluate(() => new Promise((resolve) => {
    let frames = 0;
    const start = performance.now();
    function tick() {
      frames++;
      if (performance.now() - start < 3000) requestAnimationFrame(tick);
      else resolve(+(frames / ((performance.now() - start) / 1000)).toFixed(1));
    }
    requestAnimationFrame(tick);
  }));
  console.log(JSON.stringify({ info, fps }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

